function renderP6FieldChooser(state, history) {
  const t5 = getWorkspaceLabels(state.locale);
  const registry = state.p6FieldRegistry;
  const layout = state.p6Layout;
  if (!registry || !layout) return "";
  const inLayout = new Set(layout.columns.map((column) => column.field_id));
  const available = registry.fields.filter((field2) => !inLayout.has(field2.field_id));
  const orderedColumns = layout.columns.slice().sort((a, b) => a.order - b.order);
  const visibleColumns = orderedColumns.filter((column) => column.visible);
  const hiddenColumns = orderedColumns.filter((column) => !column.visible);
  const noticeText = history?.noticeKey ? {
    undone: t5.layoutUndone,
    redone: t5.layoutRedone,
    restored: t5.layoutRestored,
    empty: t5.layoutHistoryEmpty,
    failed: t5.layoutSaveFailed,
    conflict: t5.layoutConflict
  }[history.noticeKey] : null;
  const notice = noticeText ? `<output class="cp-p6-history-notice" role="status" aria-live="polite">${escapeHtml(noticeText)}</output>` : "";
  const restorable = (history?.revisions ?? []).filter((item) => item.revision < layout.revision);
  const restoreOptions = restorable.map((item) => `<option value="${item.revision}">R${item.revision} \xB7 ${item.columnCount} ${escapeHtml(t5.columnUnit)}</option>`).join("");
  const restoreControl = history ? `<span class="cp-p6-history-restore"><label>${escapeHtml(t5.revisionOption)} <select data-p6-layout-revision-select aria-label="${escapeAttribute(t5.restore)}" title="${escapeAttribute(t5.layoutHistory)}" ${restoreOptions ? "" : "disabled"}>${restoreOptions || `<option value="">${escapeHtml(t5.layoutHistoryEmpty)}</option>`}</select></label><button type="button" data-p6-layout-restore title="${escapeAttribute(t5.restore)}" aria-label="${escapeAttribute(t5.restore)}" ${restoreOptions ? "" : "disabled"}>${escapeHtml(t5.restore)}</button></span>` : "";
  return `<section class="cp-p6-field-chooser" aria-label="${escapeAttribute(t5.fieldChooser)}">
    <div class="cp-p6-field-chooser-heading">
      <strong>${escapeHtml(t5.fields)}</strong><span>Field Registry \xB7 ${layout.scope} \xB7 R${layout.revision}</span>
    </div>
    <div class="cp-p6-history-bar" aria-label="${escapeAttribute(t5.layoutHistory)}">
      <button type="button" data-p6-layout-undo title="${escapeAttribute(t5.undo)}" ${history?.canUndo ? "" : "disabled"}>\u21B6 ${escapeHtml(t5.undo)}</button>
      <button type="button" data-p6-layout-redo title="${escapeAttribute(t5.redo)}" ${history?.canRedo ? "" : "disabled"}>\u21B7 ${escapeHtml(t5.redo)}</button>
      ${restoreControl}
      ${notice}
    </div>
    <div class="cp-p6-field-list">
      ${visibleColumns.map((column, index) => {
    const field2 = registry.fields.find((item) => item.field_id === column.field_id);
    if (!field2) return "";
    return `<span class="cp-p6-field-item"><input type="text" data-p6-field-rename="${escapeAttribute(field2.field_id)}" value="${escapeAttribute(column.label ?? field2.display_name)}" aria-label="${escapeAttribute(t5.rename)}" title="${escapeAttribute(t5.rename)}"><button type="button" data-p6-field-remove="${escapeAttribute(field2.field_id)}" title="${escapeAttribute(t5.remove + ": " + (column.label ?? field2.display_name))}" aria-label="${escapeAttribute(t5.remove + ": " + (column.label ?? field2.display_name))}">${escapeHtml(t5.remove)}</button><button type="button" data-p6-field-visibility="${escapeAttribute(field2.field_id)}" title="${escapeAttribute(t5.hide + ": " + (column.label ?? field2.display_name))}" aria-label="${escapeAttribute(t5.hide + ": " + (column.label ?? field2.display_name))}">\u25CC</button><button type="button" data-p6-field-move="${escapeAttribute(field2.field_id)}" data-p6-field-direction="up" title="${escapeAttribute(t5.moveUp)}" aria-label="${escapeAttribute(t5.moveUp)}" ${index === 0 ? "disabled" : ""}>\u2191</button><button type="button" data-p6-field-move="${escapeAttribute(field2.field_id)}" data-p6-field-direction="down" title="${escapeAttribute(t5.moveDown)}" aria-label="${escapeAttribute(t5.moveDown)}" ${index === visibleColumns.length - 1 ? "disabled" : ""}>\u2193</button><button type="button" data-p6-field-width="${escapeAttribute(field2.field_id)}" data-p6-field-width-delta="decrease" title="${escapeAttribute(t5.narrower)}" aria-label="${escapeAttribute(t5.narrower)}">\u2212</button><button type="button" data-p6-field-width="${escapeAttribute(field2.field_id)}" data-p6-field-width-delta="increase" title="${escapeAttribute(t5.wider)}" aria-label="${escapeAttribute(t5.wider)}">+</button><button type="button" data-p6-field-alignment="${escapeAttribute(field2.field_id)}" data-p6-field-alignment-value="start" title="${escapeAttribute(t5.alignStart)}" aria-label="${escapeAttribute(t5.alignStart)}" aria-pressed="${column.alignment === "start" ? "true" : "false"}">L</button><button type="button" data-p6-field-alignment="${escapeAttribute(field2.field_id)}" data-p6-field-alignment-value="center" title="${escapeAttribute(t5.alignCenter)}" aria-label="${escapeAttribute(t5.alignCenter)}" aria-pressed="${column.alignment === "center" ? "true" : "false"}">C</button><button type="button" data-p6-field-alignment="${escapeAttribute(field2.field_id)}" data-p6-field-alignment-value="end" title="${escapeAttribute(t5.alignEnd)}" aria-label="${escapeAttribute(t5.alignEnd)}" aria-pressed="${column.alignment === "end" ? "true" : "false"}">R</button><button type="button" data-p6-field-pin="${escapeAttribute(field2.field_id)}" data-p6-field-pinned="${column.pinned ? "true" : "false"}" title="${escapeAttribute(column.pinned ? t5.unpin : t5.pin)}" aria-label="${escapeAttribute(column.pinned ? t5.unpin : t5.pin)}" aria-pressed="${column.pinned ? "true" : "false"}">\u{1F4CC}</button><button type="button" data-p6-field-freeze="${escapeAttribute(field2.field_id)}" data-p6-field-frozen="${column.frozen ? "true" : "false"}" title="${escapeAttribute(column.frozen ? t5.unfreeze : t5.freeze)}" aria-label="${escapeAttribute(column.frozen ? t5.unfreeze : t5.freeze)}" aria-pressed="${column.frozen ? "true" : "false"}">\u2744</button></span>`;
  }).join("")}
      ${hiddenColumns.map((column) => {
    const field2 = registry.fields.find((item) => item.field_id === column.field_id);
    if (!field2) return "";
    return `<span class="cp-p6-field-item is-hidden"><button type="button" data-p6-field-visibility="${escapeAttribute(field2.field_id)}" data-p6-field-visible="true" title="${escapeAttribute(t5.show + ": " + (column.label ?? field2.display_name))}" aria-label="${escapeAttribute(t5.show + ": " + (column.label ?? field2.display_name))}">${escapeHtml(column.label ?? field2.display_name)}</button><button type="button" data-p6-field-remove="${escapeAttribute(field2.field_id)}" title="${escapeAttribute(t5.remove + ": " + (column.label ?? field2.display_name))}" aria-label="${escapeAttribute(t5.remove + ": " + (column.label ?? field2.display_name))}">${escapeHtml(t5.remove)}</button></span>`;
  }).join("")}
      ${available.map((field2) => `<button type="button" data-p6-field-add="${escapeAttribute(field2.field_id)}" title="${escapeAttribute(t5.add)}">${escapeHtml(field2.display_name)}</button>`).join("")}
    </div>
  </section>`;
}
