      <label class="cp-schedule-option"><span>${safe(labels5.mode)}</span><select name="mode"><option value="DATE_BASED" ${initial.mode === "DATE_BASED" ? "selected" : ""}>${safe(locale2 === "fa" ? "\u062A\u0627\u0631\u06CC\u062E\u200C\u0645\u062D\u0648\u0631" : "Date based")}</option><option value="TIME_AWARE" ${initial.mode === "TIME_AWARE" ? "selected" : ""}>${safe(locale2 === "fa" ? "\u0632\u0645\u0627\u0646\u200C\u0645\u062D\u0648\u0631" : "Time aware")}</option></select></label>
