var WORKSPACE_WINDOWS_STORAGE_KEY = "cubi:workspace-windows";
var DEFAULT_OPEN_WINDOWS = ["schedule", "project"];
var WINDOW_ORDER2 = WORKSPACE_NAVIGATION.map((item) => item.key);
var MAX_OPEN_WINDOWS = WINDOW_ORDER2.length;
function isWorkspaceWindowKey(value) {
  return WINDOW_ORDER2.includes(value);
}
function normalizeOpenWindows(values) {
  const requested = new Set(values.filter(isWorkspaceWindowKey));
  const ordered = WINDOW_ORDER2.filter((key) => requested.has(key));
  return ordered.length ? ordered : [...DEFAULT_OPEN_WINDOWS];
}
function openWorkspaceWindow(open, key) {
  if (!isWorkspaceWindowKey(key)) return normalizeOpenWindows(open);
  return normalizeOpenWindows([...open, key]);
}
function closeWorkspaceWindow(open, key, active) {
  const current = normalizeOpenWindows(open);
  if (current.length <= 1) return { open: current, active };
  const next = current.filter((item) => item !== key);
  if (!next.length) return { open: current, active };
  const nextActive = active === key ? next[next.length - 1] : active;
  return { open: next, active: nextActive };
}
function readWorkspaceWindows(storage = browserStorage2()) {
  const raw = readStoredValue(WORKSPACE_WINDOWS_STORAGE_KEY, storage);
  if (!raw) return [...DEFAULT_OPEN_WINDOWS];
  try {
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [...DEFAULT_OPEN_WINDOWS];
    return normalizeOpenWindows(
      parsed.filter((value) => typeof value === "string").slice(0, MAX_OPEN_WINDOWS)
    );
  } catch {
    return [...DEFAULT_OPEN_WINDOWS];
  }
}
function rememberWorkspaceWindows(open, storage = browserStorage2()) {
  writeStoredValue(
    WORKSPACE_WINDOWS_STORAGE_KEY,
    JSON.stringify(normalizeOpenWindows(open)),
    storage
  );
}
function browserStorage2() {
  try {
    return typeof window === "undefined" ? null : window.localStorage;
  } catch {
    return null;
  }
}

