var CAL_DAY_ORDER = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
var CAL_DAY_NAMES = {
  Sun: ["Sun", "\u06CC\u06A9\u0634\u0646\u0628\u0647"],
  Mon: ["Mon", "\u062F\u0648\u0634\u0646\u0628\u0647"],
  Tue: ["Tue", "\u0633\u0647\u200C\u0634\u0646\u0628\u0647"],
  Wed: ["Wed", "\u0686\u0647\u0627\u0631\u0634\u0646\u0628\u0647"],
  Thu: ["Thu", "\u067E\u0646\u062C\u0634\u0646\u0628\u0647"],
  Fri: ["Fri", "\u062C\u0645\u0639\u0647"],
  Sat: ["Sat", "\u0634\u0646\u0628\u0647"]
};
var CAL_MONTHS = [
  ["November", "\u0646\u0648\u0627\u0645\u0628\u0631", 2026, 10],
  ["December", "\u062F\u0633\u0627\u0645\u0628\u0631", 2026, 11],
  ["January", "\u0698\u0627\u0646\u0648\u06CC\u0647", 2027, 0],
  ["February", "\u0641\u0648\u0631\u06CC\u0647", 2027, 1],
  ["March", "\u0645\u0627\u0631\u0633", 2027, 2],
  ["April", "\u0622\u0648\u0631\u06CC\u0644", 2027, 3],
  ["May", "\u0645\u0647", 2027, 4]
];
var CAL_NONWORK = /* @__PURE__ */ new Set(["Thu", "Fri"]);
function calendarGrid(locale2, year, month) {
  const order = locale2.startsWith("fa") ? ["Sat", "Sun", "Mon", "Tue", "Wed", "Thu", "Fri"] : [...CAL_DAY_ORDER];
  const first = new Date(Date.UTC(year, month, 1));
  const lead = order.indexOf(CAL_DAY_ORDER[first.getUTCDay()]);
  const total = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  const heads = order.map((key) => `<span class="is-head">${esc5(t4(locale2, CAL_DAY_NAMES[key][0], CAL_DAY_NAMES[key][1]))}</span>`).join("");
  const blanks = Array.from({ length: lead }, () => "<span></span>").join("");
  const cells = Array.from({ length: total }, (_, offset) => {
    const dayNumber = offset + 1;
    const key = CAL_DAY_ORDER[(first.getUTCDay() + offset) % 7];
    const isDataDate = year === 2026 && month === 11 && dayNumber === 3;
    return `<span class="${CAL_NONWORK.has(key) ? "is-holiday" : ""}${isDataDate ? " is-today" : ""}"${isDataDate ? ` title="${esc5(t4(locale2, "Data date", "\u062A\u0627\u0631\u06CC\u062E \u062F\u0627\u062F\u0647"))}"` : ""}>${dayNumber}</span>`;
  }).join("");
  return heads + blanks + cells;
}
function renderCalendars(state) {
  const fa = state.locale.startsWith("fa");
  const index = Math.max(0, Math.min(CAL_MONTHS.length - 1, state.calendarMonth));
  const [enMonth, faMonth, year, month] = CAL_MONTHS[index];
  const order = fa ? ["Sat", "Sun", "Mon", "Tue", "Wed", "Thu", "Fri"] : [...CAL_DAY_ORDER];
  const dayRows = order.map((key) => `<tr><td>${esc5(t4(state.locale, CAL_DAY_NAMES[key][0], CAL_DAY_NAMES[key][1]))}</td><td>${CAL_NONWORK.has(key) ? esc5(t4(state.locale, "Nonwork", "\u062A\u0639\u0637\u06CC\u0644")) : "08:00 \u2013 16:00"}</td></tr>`).join("");
  const monthLabel = fa ? `${faMonth} ${year === 2026 ? "\u06F2\u06F0\u06F2\u06F6" : "\u06F2\u06F0\u06F2\u06F7"}` : `${enMonth} ${year}`;
  return `<section class="cp-vd-windowbody"><header class="cp-vd-winhead"><h2>${esc5(t4(state.locale, "Calendars", "\u062A\u0642\u0648\u06CC\u0645\u200C\u0647\u0627"))}</h2><div class="cp-vd-winactions"><button type="button" class="cp-vd-btn" data-vd-dialog="calendar">${esc5(t4(state.locale, "Calendar editor", "\u0648\u06CC\u0631\u0627\u06CC\u0634 \u062A\u0642\u0648\u06CC\u0645"))}</button></div></header>
    <div class="cp-vd-cal-layout">
      <div class="cp-vd-calendar">
        <div class="cp-vd-cal-head">
          <button type="button" data-vd-cal-prev ${index === 0 ? "disabled" : ""} aria-label="${esc5(t4(state.locale, "Previous month", "\u0645\u0627\u0647 \u0642\u0628\u0644"))}">${fa ? "\u203A" : "\u2039"}</button>
          <strong>${esc5(monthLabel)}</strong>
          <button type="button" data-vd-cal-next ${index === CAL_MONTHS.length - 1 ? "disabled" : ""} aria-label="${esc5(t4(state.locale, "Next month", "\u0645\u0627\u0647 \u0628\u0639\u062F"))}">${fa ? "\u2039" : "\u203A"}</button>
        </div>
        <div class="cp-vd-cal-grid">${calendarGrid(state.locale, year, month)}</div>
        <div class="cp-vd-legend"><span class="is-standard">${esc5(t4(state.locale, "Standard", "\u0627\u0633\u062A\u0627\u0646\u062F\u0627\u0631\u062F"))}</span><span class="is-nonwork">${esc5(t4(state.locale, "Nonwork", "\u062A\u0639\u0637\u06CC\u0644"))}</span><span class="is-datadate">${esc5(t4(state.locale, "Data date", "\u062A\u0627\u0631\u06CC\u062E \u062F\u0627\u062F\u0647"))}</span></div>
      </div>
      <aside class="cp-vd-cal-side">
        <h3>${esc5(t4(state.locale, "5-Day Workweek (Sat\u2013Wed)", "\u0647\u0641\u062A\u0647\u0654 \u06A9\u0627\u0631\u06CC \u06F5 \u0631\u0648\u0632\u0647 (\u0634\u0646\u0628\u0647\u2013\u0686\u0647\u0627\u0631\u0634\u0646\u0628\u0647)"))}</h3>
        <table class="cp-vd-mini"><thead><tr><th>${esc5(t4(state.locale, "Day", "\u0631\u0648\u0632"))}</th><th>${esc5(t4(state.locale, "Work hours", "\u0633\u0627\u0639\u062A \u06A9\u0627\u0631\u06CC"))}</th></tr></thead><tbody>${dayRows}</tbody></table>
        <p class="cp-vd-note">${esc5(t4(state.locale, "Sample calendar for visual review. Holidays and work hours are fixed demo data.", "\u062A\u0642\u0648\u06CC\u0645 \u0646\u0645\u0648\u0646\u0647 \u0628\u0631\u0627\u06CC \u0628\u0627\u0632\u0628\u06CC\u0646\u06CC \u0628\u0635\u0631\u06CC. \u062A\u0639\u0637\u06CC\u0644\u0627\u062A \u0648 \u0633\u0627\u0639\u062A \u06A9\u0627\u0631\u06CC \u062F\u0627\u062F\u0647\u0654 \u062B\u0627\u0628\u062A \u0646\u0645\u0627\u06CC\u0634\u06CC \u0627\u0633\u062A."))}</p>
      </aside>
    </div></section>`;
}
