    "new-project": ["New Project", "\u067E\u0631\u0648\u0698\u0647\u0654 \u062C\u062F\u06CC\u062F"],
    "project-properties": ["Project Properties", "\u0645\u0634\u062E\u0635\u0627\u062A \u067E\u0631\u0648\u0698\u0647"],
    calendar: ["Calendar Editor", "\u0648\u06CC\u0631\u0627\u06CC\u0634 \u062A\u0642\u0648\u06CC\u0645"],
    schedule: ["Schedule", "\u0632\u0645\u0627\u0646\u200C\u0628\u0646\u062F\u06CC"],
    level: ["Level Resources", "\u062A\u0633\u0637\u06CC\u062D \u0645\u0646\u0627\u0628\u0639"],
